//! `mori-k2`: thin command line over the driver library. UNADOPTED, never built or run.
//!
//! Effects per subcommand (no network code exists in this crate):
//! - `compile`: reads source and selector; checks the descriptor's fixed profile
//!   (`check_profile`); prints the relation descriptor; writes nothing.
//! - `inspect`: reads source and request and takes a declared VK digest; prints the ordinary
//!   statement receipt (decoded statement values and the fixed setup-mode matrices' decision);
//!   writes nothing and draws no randomness.
//! - `setup`: reads source and selector; draws OsRng; writes the public setup record and the
//!   proving key (mode 0600). Both outputs are created with `create_new`.
//! - `prove`: reads source, request, setup record and proving key; draws OsRng; writes the
//!   proof export with `create_new`.
//! - `verify`: reads the setup record, the proof export and optionally the source; prints a
//!   report; writes nothing and draws no randomness.
//!
//! Exit status: 0 success, 1 refusal, 2 usage error. No retry, fallback or chaining.
use mori_k2_driver::{DriverError, compile_selected, export, hexutil, input, inspect, prove, relation, setup, verify};
use std::collections::BTreeMap;
use std::fs::OpenOptions;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

const USAGE: &str = "\
mori-k2 compile --source FILE --selector FILE
mori-k2 inspect --source FILE --request FILE --vk-digest HEX
mori-k2 setup   --source FILE --selector FILE --out-record FILE --out-proving-key FILE
mori-k2 prove   --source FILE --request FILE --setup-record FILE --proving-key FILE --out-proof FILE
mori-k2 verify  --setup-record FILE --proof FILE [--source FILE]";

enum CliError {
    Usage(String),
    Refused(DriverError),
}

impl From<DriverError> for CliError {
    fn from(e: DriverError) -> Self {
        Self::Refused(e)
    }
}

fn main() -> ExitCode {
    let mut args = Vec::new();
    for a in std::env::args_os().skip(1) {
        match a.into_string() {
            Ok(s) => args.push(s),
            Err(_) => {
                eprintln!("usage: arguments must be UTF-8\n{USAGE}");
                return ExitCode::from(2);
            }
        }
    }
    match run(&args) {
        Ok(()) => ExitCode::SUCCESS,
        Err(CliError::Usage(m)) => {
            eprintln!("usage: {m}\n{USAGE}");
            ExitCode::from(2)
        }
        Err(CliError::Refused(e)) => {
            eprintln!("refused: {e}");
            ExitCode::from(1)
        }
    }
}

/// Parses `--flag value` pairs. Every flag must be allowed, appear at most once and have a
/// value; every required flag must be present. No positional arguments.
fn flags(args: &[String], required: &[&str], optional: &[&str]) -> Result<BTreeMap<String, PathBuf>, CliError> {
    let mut out = BTreeMap::new();
    let mut i = 0;
    while i < args.len() {
        let name = args[i].strip_prefix("--").ok_or_else(|| CliError::Usage(format!("unexpected argument {:?}", args[i])))?;
        if !required.contains(&name) && !optional.contains(&name) {
            return Err(CliError::Usage(format!("unknown flag --{name}")));
        }
        let value = args.get(i + 1).ok_or_else(|| CliError::Usage(format!("--{name} needs a value")))?;
        if value.is_empty() || value.starts_with("--") {
            return Err(CliError::Usage(format!("--{name} needs a path value")));
        }
        if out.insert(name.to_string(), PathBuf::from(value)).is_some() {
            return Err(CliError::Usage(format!("--{name} given twice")));
        }
        i += 2;
    }
    for r in required {
        if !out.contains_key(*r) {
            return Err(CliError::Usage(format!("missing --{r}")));
        }
    }
    Ok(out)
}

fn path<'a>(f: &'a BTreeMap<String, PathBuf>, name: &str) -> Result<&'a Path, CliError> {
    f.get(name).map(PathBuf::as_path).ok_or_else(|| CliError::Usage(format!("missing --{name}")))
}

/// A flag whose value is text rather than a path (`--vk-digest`).
fn text<'a>(f: &'a BTreeMap<String, PathBuf>, name: &str) -> Result<&'a str, CliError> {
    path(f, name)?.to_str().ok_or_else(|| CliError::Usage(format!("--{name} must be UTF-8")))
}

fn json_bytes(p: &Path, what: &str) -> Result<Vec<u8>, DriverError> {
    input::read_bounded(p, input::MAX_JSON_BYTES as u64, what)
}

/// Creates `p` exclusively and writes `bytes`. An existing path is refused, never replaced.
fn write_new(p: &Path, bytes: &[u8], private: bool) -> Result<(), DriverError> {
    let mut options = OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.mode(if private { 0o600 } else { 0o644 });
    }
    #[cfg(not(unix))]
    let _ = private;
    let mut file = options.open(p).map_err(|e| DriverError::Io(format!("cannot create {}: {e}", p.display())))?;
    file.write_all(bytes).map_err(|e| DriverError::Io(format!("cannot write {}: {e}", p.display())))?;
    file.sync_all().map_err(|e| DriverError::Io(format!("cannot sync {}: {e}", p.display())))?;
    Ok(())
}

fn refuse_existing(paths: &[&Path]) -> Result<(), DriverError> {
    for p in paths {
        if p.exists() {
            return Err(DriverError::Io(format!("{} already exists; outputs are never overwritten", p.display())));
        }
    }
    Ok(())
}

fn print_json<T: serde::Serialize>(value: &T) -> Result<(), DriverError> {
    let bytes = export::document_bytes(value)?;
    std::io::stdout().write_all(&bytes).map_err(|e| DriverError::Io(format!("stdout: {e}")))
}

fn run(args: &[String]) -> Result<(), CliError> {
    let (command, rest) = args.split_first().ok_or_else(|| CliError::Usage("missing subcommand".into()))?;
    match command.as_str() {
        "compile" => {
            let f = flags(rest, &["source", "selector"], &[])?;
            let source = input::read_source(path(&f, "source")?)?;
            let selector = input::parse_selector(&json_bytes(path(&f, "selector")?, "selector")?)?;
            let selected = compile_selected(&source, &selector)?;
            selected.descriptor().check_profile()?;
            print_json(selected.descriptor())?;
            Ok(())
        }
        "inspect" => {
            let f = flags(rest, &["source", "request", "vk-digest"], &[])?;
            let vk_digest = hexutil::decode_exact::<32>(text(&f, "vk-digest")?, "--vk-digest")?;
            let source = input::read_source(path(&f, "source")?)?;
            let request = input::parse_request(&json_bytes(path(&f, "request")?, "request")?)?;
            let selected = compile_selected(&source, &request.selector)?;
            selected.descriptor().check_profile()?;
            let receipt = inspect::inspect(&selected, &request, vk_digest)?;
            print_json(&receipt)?;
            Ok(())
        }
        "setup" => {
            let f = flags(rest, &["source", "selector", "out-record", "out-proving-key"], &[])?;
            let (out_record, out_pk) = (path(&f, "out-record")?, path(&f, "out-proving-key")?);
            refuse_existing(&[out_record, out_pk])?;
            let source = input::read_source(path(&f, "source")?)?;
            let selector = input::parse_selector(&json_bytes(path(&f, "selector")?, "selector")?)?;
            let selected = compile_selected(&source, &selector)?;
            let mut rng = rand_core::OsRng;
            let out = setup::setup(&selected, &mut rng)?;
            write_new(out_pk, &out.proving_key_bytes, true)?;
            write_new(out_record, &out.record_bytes, false)?;
            print_json(&serde_json::json!({
                "setupRecordSha256": mori_r1cs::identity::digest_bytes(&out.record_bytes).hex(),
                "predicateDigest": out.record.relation.predicate_digest,
                "observedR1csSha256": out.observed_r1cs_sha256,
                "vkDigestBlake2b256": out.record.vk_digest_blake2b256,
                "provingKeySha256": out.record.proving_key_sha256,
                "trustProfile": out.record.trust_profile,
            }))?;
            Ok(())
        }
        "prove" => {
            let f = flags(rest, &["source", "request", "setup-record", "proving-key", "out-proof"], &[])?;
            let out_proof = path(&f, "out-proof")?;
            refuse_existing(&[out_proof])?;
            let source = input::read_source(path(&f, "source")?)?;
            let request = input::parse_request(&json_bytes(path(&f, "request")?, "request")?)?;
            let selected = compile_selected(&source, &request.selector)?;
            let setup = export::parse_setup_record(&json_bytes(path(&f, "setup-record")?, "setup record")?)?;
            relation::require_same(&setup.record.relation, selected.descriptor())?;
            let pk_bytes = input::read_bounded(path(&f, "proving-key")?, input::MAX_PROVING_KEY_BYTES, "proving key")?;
            let pk = prove::load_proving_key(&pk_bytes, &setup)?;
            drop(pk_bytes);
            let mut rng = rand_core::OsRng;
            let out = prove::prove(&selected, &setup, &pk, &request, &mut rng)?;
            write_new(out_proof, &out.export_bytes, false)?;
            print_json(&serde_json::json!({
                "proofExportSha256": mori_r1cs::identity::digest_bytes(&out.export_bytes).hex(),
                "statementDigestBlake2b256": out.export.statement_digest_blake2b256,
                "x1": out.export.public_inputs.x1,
                "x2": out.export.public_inputs.x2,
            }))?;
            Ok(())
        }
        "verify" => {
            let f = flags(rest, &["setup-record", "proof"], &["source"])?;
            let record_bytes = json_bytes(path(&f, "setup-record")?, "setup record")?;
            let export_bytes = json_bytes(path(&f, "proof")?, "proof export")?;
            let recompiled = match f.get("source") {
                Some(p) => {
                    let setup = export::parse_setup_record(&record_bytes)?;
                    let source = input::read_source(p)?;
                    Some(compile_selected(&source, &relation::selector_for(&setup.record.relation))?)
                }
                None => None,
            };
            let report = verify::verify_export(&record_bytes, &export_bytes, recompiled.as_ref())?;
            print_json(&report)?;
            Ok(())
        }
        other => Err(CliError::Usage(format!("unknown subcommand {other:?}"))),
    }
}

//! Bounded input reading and strict request parsing.
//!
//! Every JSON document goes through `mori_core::json::parse_limited` first: duplicate decoded
//! keys, trailing data, depth above 32 and more than 65,536 nodes are refused there. The value
//! is then decoded into `deny_unknown_fields` DTOs. Hex and decimal fields are checked by
//! [`crate::hexutil`] where they are used, never coerced.
use crate::error::DriverError;
use mori_core::{Effect, Scenario, Snapshot, Value};
use serde::de::DeserializeOwned;
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::fs::File;
use std::io::Read;
use std::path::Path;

/// Source text ceiling (bytes).
pub const MAX_SOURCE_BYTES: u64 = 262_144;
/// JSON document ceiling; equal to Core's own `json::parse` ceiling.
pub const MAX_JSON_BYTES: usize = 1_048_576;
/// Proving-key file ceiling. The real size is unmeasured; a larger key is refused, not read.
pub const MAX_PROVING_KEY_BYTES: u64 = 2 * 1024 * 1024 * 1024;

pub const SELECTOR_FORMAT: &str = "moriarty-k2-relation-selector/1";
pub const REQUEST_FORMAT: &str = "moriarty-k2-prove-request/1";

/// Reads a regular file of at most `max` bytes. Devices, directories and larger files are
/// refused before their content is read.
pub fn read_bounded(path: &Path, max: u64, what: &str) -> Result<Vec<u8>, DriverError> {
    let file = File::open(path).map_err(|e| DriverError::Io(format!("{what}: cannot open {}: {e}", path.display())))?;
    let meta = file.metadata().map_err(|e| DriverError::Io(format!("{what}: cannot stat {}: {e}", path.display())))?;
    if !meta.is_file() {
        return Err(DriverError::Io(format!("{what}: {} is not a regular file", path.display())));
    }
    if meta.len() > max {
        return Err(DriverError::Input(format!("{what}: {} bytes exceed the {max}-byte bound", meta.len())));
    }
    let mut out = Vec::new();
    file.take(max.saturating_add(1))
        .read_to_end(&mut out)
        .map_err(|e| DriverError::Io(format!("{what}: cannot read {}: {e}", path.display())))?;
    if out.len() as u64 > max {
        return Err(DriverError::Input(format!("{what}: file grew beyond the {max}-byte bound while read")));
    }
    Ok(out)
}

/// Reads a source file as UTF-8 text.
pub fn read_source(path: &Path) -> Result<String, DriverError> {
    let bytes = read_bounded(path, MAX_SOURCE_BYTES, "source")?;
    String::from_utf8(bytes).map_err(|_| DriverError::Input("source: not UTF-8".into()))
}

/// Strict JSON decoding of `bytes` into `T`.
pub fn parse_json<T: DeserializeOwned>(bytes: &[u8], what: &str) -> Result<T, DriverError> {
    if bytes.len() > MAX_JSON_BYTES {
        return Err(DriverError::Input(format!("{what}: {} bytes exceed the JSON bound", bytes.len())));
    }
    let text = std::str::from_utf8(bytes).map_err(|_| DriverError::Input(format!("{what}: not UTF-8")))?;
    let value = mori_core::json::parse_limited(text, MAX_JSON_BYTES, "JSON input exceeds the driver bound")
        .map_err(|e| DriverError::Input(format!("{what}: {e}")))?;
    serde_json::from_value(value).map_err(|e| DriverError::Input(format!("{what}: {e}")))
}

/// Which relation to compile. Every option is spelled out; the driver supports exactly one
/// value of each and refuses the rest (see [`crate::relation::check_selector`]).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct RelationSelector {
    pub format: String,
    pub language: String,
    pub semantics: String,
    pub action: String,
    pub adapter: String,
    pub cap: String,
    pub accounting: String,
    pub frame: String,
    /// Optional pin: lowercase hex SHA-256 of the raw source bytes.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub expected_source_sha256: Option<String>,
    /// Optional pin: lowercase hex canonical typed-Program hash.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub expected_program_hash: Option<String>,
}

/// The claimed transition, as a proposal. There is no default kind.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", deny_unknown_fields)]
pub enum TransitionInput {
    /// Core `simulate` proposes the transition for this scenario.
    CoreReference { scenario: Scenario },
    /// Explicit typed records: inputs, pre and post snapshots and ordered effects.
    Records { inputs: BTreeMap<String, Value>, pre: Snapshot, post: Snapshot, effects: Vec<Effect> },
}

/// Per-proof context bytes, as caller-declared premises. The VK digest is derived from the
/// VK actually used; if a request restates it, the two must be equal.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct ContextInput {
    pub claimant_vkh: String,
    pub network_id: u8,
    pub settle_hash: String,
    pub thread_id: String,
    pub consumed_txid: String,
    pub consumed_ix: u16,
    pub seq: u64,
    pub catalogue_digest: String,
    pub intents_digest: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub vk_digest: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct ProveRequest {
    pub format: String,
    pub selector: RelationSelector,
    pub transition: TransitionInput,
    pub context: ContextInput,
}

/// Parses and format-checks a selector document.
pub fn parse_selector(bytes: &[u8]) -> Result<RelationSelector, DriverError> {
    let s: RelationSelector = parse_json(bytes, "selector")?;
    if s.format != SELECTOR_FORMAT {
        return Err(DriverError::Unsupported(format!("selector format {:?}", s.format)));
    }
    Ok(s)
}

/// Parses and format-checks a prove request.
pub fn parse_request(bytes: &[u8]) -> Result<ProveRequest, DriverError> {
    let r: ProveRequest = parse_json(bytes, "prove request")?;
    if r.format != REQUEST_FORMAT {
        return Err(DriverError::Unsupported(format!("request format {:?}", r.format)));
    }
    if r.selector.format != SELECTOR_FORMAT {
        return Err(DriverError::Unsupported(format!("selector format {:?}", r.selector.format)));
    }
    Ok(r)
}

//! Compilation through the actual frozen compiler and the descriptor of every identity a
//! compiled SettlementHashV2 relation binds.
//!
//! Nothing here builds constraints or identities by hand. `compile_selected` calls
//! `mori_r1cs::compile_source::<Fr>` (Core `language` routing, `parse`, `validate`,
//! `require_core1`, plan, layout, probe synthesis). A `moriarty/2` source is admitted by Core's
//! stage loader and refused by the compiler with `StagedNotLowered`; the driver surfaces that
//! refusal unchanged.
use crate::error::DriverError;
use crate::hexutil;
use crate::input::{RelationSelector, SELECTOR_FORMAT};
use ark_bls12_381::Fr;
use ark_ff::{BigInteger, PrimeField};
use ark_relations::r1cs::ConstraintMatrices;
use mori_r1cs::abi2::{FAMILY_V2, HEADER_LEN, STMT_TAG};
use mori_r1cs::identity::{self, Digest32};
use mori_r1cs::{AccountingBinding, CapBinding, CompileOptions, CompiledRelation, CompilerBuild, FrameCells, StatementAdapter};
use serde::{Deserialize, Serialize};

pub const LANGUAGE: &str = "moriarty/1";
pub const SEMANTICS: &str = "moriarty-core/1";
pub const CAP: &str = "NotBound";
pub const ACCOUNTING: &str = "GrossDebitAndFees";
pub const FRAME: &str = "TouchedOnly";
/// SettlementHashV2 public inputs: the two 128-bit digest halves.
pub const PUBLIC_INPUTS: u8 = 2;
/// arkworks counts the constant-one instance variable: 1 + 2.
pub const INSTANCE_VARIABLES: u64 = 3;

/// Refuses every selector value outside the one supported profile. Runs before compilation.
pub fn check_selector(s: &RelationSelector) -> Result<(), DriverError> {
    let fixed = [
        ("format", s.format.as_str(), SELECTOR_FORMAT),
        ("language", s.language.as_str(), LANGUAGE),
        ("semantics", s.semantics.as_str(), SEMANTICS),
        ("adapter", s.adapter.as_str(), crate::ADAPTER),
        ("cap", s.cap.as_str(), CAP),
        ("accounting", s.accounting.as_str(), ACCOUNTING),
        ("frame", s.frame.as_str(), FRAME),
    ];
    for (what, got, want) in fixed {
        if got != want {
            return Err(DriverError::Unsupported(format!("selector {what} {got:?}; this driver supports only {want:?}")));
        }
    }
    if s.action.is_empty() || s.action.len() > 1024 {
        return Err(DriverError::Input("selector action must contain 1..1024 bytes".into()));
    }
    Ok(())
}

/// The selector that recompiles the relation a descriptor names (verify with `--source`).
pub fn selector_for(desc: &RelationDescriptor) -> RelationSelector {
    RelationSelector {
        format: SELECTOR_FORMAT.into(),
        language: desc.language.clone(),
        semantics: desc.semantics.clone(),
        action: desc.action.clone(),
        adapter: desc.adapter.clone(),
        cap: CAP.into(),
        accounting: ACCOUNTING.into(),
        frame: FRAME.into(),
        expected_source_sha256: desc.source_sha256.clone(),
        expected_program_hash: Some(desc.program_hash.clone()),
    }
}

/// Every identity of one compiled SettlementHashV2 relation, as lowercase hex or decimal.
/// Built only by [`RelationDescriptor::of`] from an actual compilation.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct RelationDescriptor {
    pub relation_format: String,
    pub relation_version: u64,
    pub language: String,
    pub semantics: String,
    pub logical_cost_profile: String,
    pub profile_digest: String,
    pub program_hash: String,
    /// Raw source bytes; declared provenance, never bound in-circuit.
    pub source_sha256: Option<String>,
    pub action: String,
    pub action_index: u16,
    /// mori-r1cs `mori-r1cs-shape/1` digest (SHA-256), a header constant inside the predicate.
    pub relation_shape_digest: String,
    pub compiler_source_manifest_sha256: String,
    pub core_closure_sha256: String,
    pub compiler_build_digest: String,
    pub adapter: String,
    pub logical_work: String,
    /// `RelationIdentity::digest()`; statement bytes 48..80 and the catalogue entry.
    pub predicate_digest: String,
    /// BLAKE2b-256 of the `MRG16-PVC-SHP-02` bytes; statement bytes 80..112.
    pub abi2_shape_digest: String,
    pub abi2_shape_bytes_hex: String,
    pub body_len: u32,
    pub statement_tag_hex: String,
    pub family_id_hex: String,
    pub header_len: u32,
    pub field_modulus_le_hex: String,
    /// `mori-r1cs-matrices/1` digest of the probe synthesis.
    pub r1cs_sha256: String,
    pub constraints: u64,
    pub instance_variables: u64,
    pub witness_variables: u64,
    pub public_input_count: u8,
}

fn count(n: usize, what: &str) -> Result<u64, DriverError> {
    u64::try_from(n).map_err(|_| DriverError::Backend(format!("{what} exceeds u64")))
}

impl RelationDescriptor {
    /// Reads every identity from the compiled relation. Refuses a relation that is not
    /// SettlementHashV2 or whose predicate constant differs from its identity digest.
    pub fn of(relation: &CompiledRelation) -> Result<Self, DriverError> {
        if relation.adapter() != StatementAdapter::SettlementHashV2 {
            return Err(DriverError::Unsupported("relation adapter is not SettlementHashV2".into()));
        }
        let consts = relation
            .abi2()
            .ok_or_else(|| DriverError::Backend("SettlementHashV2 relation without ABI v2 constants".into()))?;
        let id = relation.identity();
        let predicate = id.digest().map_err(DriverError::Compile)?;
        if predicate.0 != consts.predicate_digest {
            return Err(DriverError::Backend("ABI v2 predicate constant differs from RelationIdentity::digest()".into()));
        }
        let probe = relation.probe();
        let header_len = u32::try_from(HEADER_LEN).map_err(|_| DriverError::Backend("header length".into()))?;
        Ok(Self {
            relation_format: id.relation_format.clone(),
            relation_version: id.relation_version,
            language: id.language.clone(),
            semantics: id.semantics.clone(),
            logical_cost_profile: id.logical_cost_profile.clone(),
            profile_digest: id.profile_digest.hex(),
            program_hash: id.program_hash.hex(),
            source_sha256: id.source_sha256.map(|d| d.hex()),
            action: id.action.clone(),
            action_index: id.action_index,
            relation_shape_digest: id.shape_digest.hex(),
            compiler_source_manifest_sha256: id.compiler_build.compiler_source_manifest_sha256.hex(),
            core_closure_sha256: id.compiler_build.core_closure_sha256.hex(),
            compiler_build_digest: id.compiler_build_digest.hex(),
            adapter: crate::ADAPTER.into(),
            logical_work: id.logical_work.0.to_string(),
            predicate_digest: hexutil::encode(&consts.predicate_digest),
            abi2_shape_digest: hexutil::encode(&consts.shape_digest),
            abi2_shape_bytes_hex: hexutil::encode(&consts.shape_bytes),
            body_len: consts.body_len,
            statement_tag_hex: hexutil::encode(STMT_TAG),
            family_id_hex: hexutil::encode(FAMILY_V2),
            header_len,
            field_modulus_le_hex: probe.field_modulus_le_hex.clone(),
            r1cs_sha256: probe.r1cs_sha256.hex(),
            constraints: count(probe.constraints, "constraints")?,
            instance_variables: count(probe.instance_variables, "instance variables")?,
            witness_variables: count(probe.witness_variables, "witness variables")?,
            public_input_count: PUBLIC_INPUTS,
        })
    }

    /// Syntax and profile checks on a descriptor read from a file (no recompilation).
    pub fn check_profile(&self) -> Result<(), DriverError> {
        let fixed = [
            ("language", self.language.as_str(), LANGUAGE),
            ("semantics", self.semantics.as_str(), SEMANTICS),
            ("adapter", self.adapter.as_str(), crate::ADAPTER),
        ];
        for (what, got, want) in fixed {
            if got != want {
                return Err(DriverError::Unsupported(format!("descriptor {what} {got:?}; expected {want:?}")));
            }
        }
        for (what, value) in [
            ("profileDigest", &self.profile_digest),
            ("programHash", &self.program_hash),
            ("relationShapeDigest", &self.relation_shape_digest),
            ("compilerSourceManifestSha256", &self.compiler_source_manifest_sha256),
            ("coreClosureSha256", &self.core_closure_sha256),
            ("compilerBuildDigest", &self.compiler_build_digest),
            ("predicateDigest", &self.predicate_digest),
            ("abi2ShapeDigest", &self.abi2_shape_digest),
            ("r1csSha256", &self.r1cs_sha256),
        ] {
            hexutil::decode_exact::<32>(value, what)?;
        }
        if let Some(s) = &self.source_sha256 {
            hexutil::decode_exact::<32>(s, "sourceSha256")?;
        }
        hexutil::parse_u128_decimal(&self.logical_work, "logicalWork")?;
        if self.statement_tag_hex != hexutil::encode(STMT_TAG) || self.family_id_hex != hexutil::encode(FAMILY_V2) {
            return Err(DriverError::Unsupported("descriptor statement tag or family id is not ABI v2".into()));
        }
        if self.header_len as usize != HEADER_LEN {
            return Err(DriverError::Unsupported("descriptor header length is not 343".into()));
        }
        if self.public_input_count != PUBLIC_INPUTS || self.instance_variables != INSTANCE_VARIABLES {
            return Err(DriverError::Unsupported("SettlementHashV2 has exactly two public inputs".into()));
        }
        // The ABI v2 shape digest is BLAKE2b-256 of the shape bytes the descriptor carries.
        let shape = hexutil::decode_bounded(&self.abi2_shape_bytes_hex, crate::claim::MAX_STATEMENT_BYTES, "abi2ShapeBytesHex")?;
        if hexutil::encode(&mori_r1cs::blake2b::blake2b256(&shape)) != self.abi2_shape_digest {
            return Err(DriverError::mismatch("abi2ShapeDigest", hexutil::encode(&mori_r1cs::blake2b::blake2b256(&shape)), self.abi2_shape_digest.clone()));
        }
        Ok(())
    }
}

/// Name and values of the first descriptor field that differs, if any.
pub fn first_difference(expected: &RelationDescriptor, actual: &RelationDescriptor) -> Option<(String, String, String)> {
    let (Ok(serde_json::Value::Object(a)), Ok(serde_json::Value::Object(b))) = (serde_json::to_value(expected), serde_json::to_value(actual)) else {
        return Some(("descriptor".into(), "serializable".into(), "unserializable".into()));
    };
    for (key, va) in &a {
        let vb = b.get(key).cloned().unwrap_or(serde_json::Value::Null);
        if *va != vb {
            return Some((key.clone(), va.to_string(), vb.to_string()));
        }
    }
    for (key, vb) in &b {
        if !a.contains_key(key) {
            return Some((key.clone(), "null".into(), vb.to_string()));
        }
    }
    None
}

/// Refuses unless `actual` equals `expected` in every field.
pub fn require_same(expected: &RelationDescriptor, actual: &RelationDescriptor) -> Result<(), DriverError> {
    match first_difference(expected, actual) {
        None => Ok(()),
        Some((field, e, a)) => Err(DriverError::mismatch(format!("relation descriptor field {field}"), e, a)),
    }
}

/// A relation compiled by the actual compiler for one selector, with its descriptor.
#[derive(Debug, Clone)]
pub struct SelectedRelation {
    selector: RelationSelector,
    relation: CompiledRelation,
    descriptor: RelationDescriptor,
}

impl SelectedRelation {
    pub fn selector(&self) -> &RelationSelector {
        &self.selector
    }
    pub fn relation(&self) -> &CompiledRelation {
        &self.relation
    }
    pub fn descriptor(&self) -> &RelationDescriptor {
        &self.descriptor
    }
}

/// Compiles `source` for `selector` with the actual compiler, then checks optional pins.
pub fn compile_selected(source: &str, selector: &RelationSelector) -> Result<SelectedRelation, DriverError> {
    check_selector(selector)?;
    let options = CompileOptions {
        action: selector.action.clone(),
        cap: CapBinding::NotBound,
        frame: FrameCells::TouchedOnly,
        accounting: AccountingBinding::GrossDebitAndFees,
        compiler: CompilerBuild::embedded().map_err(DriverError::Compile)?,
    };
    let relation =
        mori_r1cs::compile_source::<Fr>(source, options, StatementAdapter::SettlementHashV2).map_err(DriverError::Compile)?;
    let descriptor = RelationDescriptor::of(&relation)?;
    if descriptor.language != selector.language || descriptor.semantics != selector.semantics {
        return Err(DriverError::mismatch(
            "language/semantics",
            format!("{}/{}", selector.language, selector.semantics),
            format!("{}/{}", descriptor.language, descriptor.semantics),
        ));
    }
    if let Some(pin) = &selector.expected_source_sha256 {
        hexutil::decode_exact::<32>(pin, "expectedSourceSha256")?;
        let actual = descriptor.source_sha256.clone().unwrap_or_default();
        if *pin != actual {
            return Err(DriverError::mismatch("source sha256", pin.clone(), actual));
        }
    }
    if let Some(pin) = &selector.expected_program_hash {
        hexutil::decode_exact::<32>(pin, "expectedProgramHash")?;
        if *pin != descriptor.program_hash {
            return Err(DriverError::mismatch("program hash", pin.clone(), descriptor.program_hash.clone()));
        }
    }
    Ok(SelectedRelation { selector: selector.clone(), relation, descriptor })
}

/// `mori-r1cs-matrices/1`: the exact byte rule of the compiler's probe (`circuit.rs:282-305`),
/// recomputed here because the probe function is private. A divergence makes `prove` refuse;
/// it can never make it accept.
pub fn matrix_digest(m: &ConstraintMatrices<Fr>) -> Digest32 {
    let mut bytes = b"mori-r1cs-matrices/1\0".to_vec();
    for n in [m.num_instance_variables, m.num_witness_variables, m.num_constraints] {
        bytes.extend_from_slice(&(n as u64).to_le_bytes());
    }
    for matrix in [&m.a, &m.b, &m.c] {
        bytes.extend_from_slice(&(matrix.len() as u64).to_le_bytes());
        for row in matrix.iter() {
            bytes.extend_from_slice(&(row.len() as u64).to_le_bytes());
            for (coefficient, index) in row.iter() {
                bytes.extend_from_slice(&(*index as u64).to_le_bytes());
                let le = coefficient.into_bigint().to_bytes_le();
                bytes.extend_from_slice(&(le.len() as u64).to_le_bytes());
                bytes.extend_from_slice(&le);
            }
        }
    }
    identity::digest_bytes(&bytes)
}

//! Ordinary statement receipt (`mori-k2 inspect`). K4H successor source; never compiled or
//! run by its author.
//!
//! For one request it prints the claimed statement, its BLAKE2b-256 digest and public inputs,
//! every body slot decoded from the statement BYTES in the compiled layout's slot order, and
//! the fixed setup-mode matrices' decision on the claim's full assignment. A reviewer compares
//! the decoded values with gold frozen before execution; the decoder never reads
//! `TransitionValues`. No randomness, key, proof, pairing or file write.
//!
//! The VK digest is caller-declared (no setup exists in this tier). Context bytes are bound by
//! the statement, not authenticated by it.
use crate::claim::{self, PreparedClaim};
use crate::error::DriverError;
use crate::fixed::{self, FixedMatrices};
use crate::hexutil;
use crate::input::ProveRequest;
use crate::relation::SelectedRelation;
use mori_r1cs::abi2::HEADER_LEN;
use mori_r1cs::{SlotEncoding, Tamper};
use serde::Serialize;
use serde_json::Value as Json;

pub const RECEIPT_FORMAT: &str = "moriarty-k2-statement-receipt/1";
pub const RECEIPT_NOTICE: &str = "Ordinary receipt: no setup, key, proof or pairing. The verdict is the fixed setup-mode matrices' decision on this claim's full assignment. The VK digest is caller-declared. Context bytes are bound, not authenticated. Values were proposed by the request, not decided by the host.";

/// One body slot as decoded from the statement bytes.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SlotValue {
    pub label: String,
    /// `uint128` (decimal string), `bool` (true/false) or `wide144` (decimal string).
    pub encoding: &'static str,
    pub value: Json,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct FixedMatrixCheck {
    pub r1cs_sha256: String,
    pub equals_descriptor: bool,
    /// The prove-mode matrices of this claim's synthesis have the fixed digest.
    pub prove_matrix_digest_equal: bool,
    pub constraints: usize,
    pub violated: usize,
    pub first_violated: Vec<usize>,
}

#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct StatementReceipt {
    pub format: &'static str,
    pub notice: &'static str,
    pub action: String,
    pub program_hash: String,
    pub predicate_digest: String,
    pub abi2_shape_digest: String,
    pub r1cs_sha256: String,
    pub declared_vk_digest: String,
    pub statement_len: usize,
    pub statement_hex: String,
    pub statement_digest_blake2b256: String,
    pub x1: String,
    pub x2: String,
    pub slots: Vec<SlotValue>,
    pub fixed_matrix: FixedMatrixCheck,
}

/// Decodes every body slot of `statement` in layout order. Refuses a statement whose length is
/// not `343 + bodyLen` or whose Bool byte is neither 0 nor 1.
pub fn decode_body(selected: &SelectedRelation, statement: &[u8]) -> Result<Vec<SlotValue>, DriverError> {
    let body_len = selected.descriptor().body_len as usize;
    if statement.len() != HEADER_LEN + body_len {
        return Err(DriverError::Input(format!("statement length {} differs from 343 + {body_len}", statement.len())));
    }
    let mut at = HEADER_LEN;
    let mut out = Vec::new();
    for slot in &selected.relation().layout().slots {
        if slot.kind.is_header() {
            continue;
        }
        let (encoding, width) = match slot.encoding {
            SlotEncoding::UInt => ("uint128", 16),
            SlotEncoding::Bool => ("bool", 1),
            SlotEncoding::Wide => ("wide144", 18),
            other => return Err(DriverError::Backend(format!("slot {} has body encoding {other:?}", slot.label))),
        };
        let bytes = statement
            .get(at..at + width)
            .ok_or_else(|| DriverError::Input(format!("statement too short for slot {}", slot.label)))?;
        let value = match encoding {
            "uint128" => {
                let mut b = [0u8; 16];
                b.copy_from_slice(bytes);
                Json::String(u128::from_be_bytes(b).to_string())
            }
            "bool" => match bytes[0] {
                0 => Json::Bool(false),
                1 => Json::Bool(true),
                x => return Err(DriverError::Input(format!("slot {} byte {x} is not a Bool", slot.label))),
            },
            _ => {
                let top = u16::from_be_bytes([bytes[0], bytes[1]]);
                let mut b = [0u8; 16];
                b.copy_from_slice(&bytes[2..18]);
                let lo = u128::from_be_bytes(b);
                Json::String(if top == 0 { lo.to_string() } else { format!("{top}*2^128+{lo}") })
            }
        };
        out.push(SlotValue { label: slot.label.clone(), encoding, value });
        at += width;
    }
    if at != statement.len() {
        return Err(DriverError::Backend("layout body slots do not cover the statement body".into()));
    }
    Ok(out)
}

/// The receipt of an already-prepared claim.
pub fn receipt(selected: &SelectedRelation, claim: &PreparedClaim) -> Result<StatementReceipt, DriverError> {
    let fixed_matrices = FixedMatrices::of(selected)?;
    let assignment = fixed::prove_assignment(selected, claim, Tamper::none(), true)?;
    if assignment.overrides_used != 0 {
        return Err(DriverError::Backend("a tamper override reached a witness in a receipt synthesis".into()));
    }
    let evaluation = fixed_matrices.evaluate(&assignment.full_assignment)?;
    let d = selected.descriptor();
    Ok(StatementReceipt {
        format: RECEIPT_FORMAT,
        notice: RECEIPT_NOTICE,
        action: d.action.clone(),
        program_hash: d.program_hash.clone(),
        predicate_digest: d.predicate_digest.clone(),
        abi2_shape_digest: d.abi2_shape_digest.clone(),
        r1cs_sha256: d.r1cs_sha256.clone(),
        declared_vk_digest: hexutil::encode(&claim.context.vk_digest),
        statement_len: claim.statement.len(),
        statement_hex: hexutil::encode(&claim.statement),
        statement_digest_blake2b256: hexutil::encode(&claim.statement_digest),
        x1: claim.public_inputs[0].to_string(),
        x2: claim.public_inputs[1].to_string(),
        slots: decode_body(selected, &claim.statement)?,
        fixed_matrix: FixedMatrixCheck {
            r1cs_sha256: fixed_matrices.digest_hex().to_string(),
            equals_descriptor: fixed_matrices.digest_hex() == d.r1cs_sha256,
            prove_matrix_digest_equal: assignment.matrix_digest_hex.as_deref() == Some(fixed_matrices.digest_hex()),
            constraints: evaluation.constraints,
            violated: evaluation.violated,
            first_violated: evaluation.first_violated,
        },
    })
}

/// Proposes the request's claim with a declared VK digest and builds its receipt. Refuses a
/// request whose selector is not the one `selected` was compiled with.
pub fn inspect(selected: &SelectedRelation, request: &ProveRequest, vk_digest: [u8; 32]) -> Result<StatementReceipt, DriverError> {
    if request.selector != *selected.selector() {
        return Err(DriverError::mismatch("request selector", "the selector the relation was compiled with", "a different selector"));
    }
    let claim = claim::prepare_claim(selected, &request.transition, &request.context, vk_digest)?;
    receipt(selected, &claim)
}

//! Admission frontend: the actual current Core parser, validator and stage loader.
//!
//! Legacy Source/5 or Source/6 and the Node beta are not frontends here. A `/1` IR
//! value built in memory (for example a DAG with shared nodes, which the parser never
//! produces) is admitted through [`admit_program`] and the same Core `validate`.
use crate::error::CompileError;
use crate::identity::{self, Digest32, ProgramIdentity};
use crate::staged::StagedAdmission;
use mori_core::Program;

/// An admitted `/1` typed Program. Only this module constructs one.
#[derive(Debug, Clone)]
pub struct AdmittedCore1 {
    program: Program,
    identity: ProgramIdentity,
}

impl AdmittedCore1 {
    pub fn program(&self) -> &Program {
        &self.program
    }
    pub fn identity(&self) -> &ProgramIdentity {
        &self.identity
    }
}

/// Result of routing a source text by its declared profile.
#[derive(Debug, Clone)]
pub enum Admitted {
    Core1(AdmittedCore1),
    Staged2(StagedAdmission),
}

/// Route by `mori_core::language`, then admit with the profile's own Core entry point.
pub fn admit_source(source: &str) -> Result<Admitted, CompileError> {
    let profile = mori_core::language(source).map_err(CompileError::Core)?;
    let source_sha256 = identity::source_hash(source);
    match profile {
        mori_core::LANGUAGE => {
            // `parse` validates before returning (parser.rs:157-159).
            let program = mori_core::parse(source).map_err(CompileError::Core)?;
            admit_checked(program, Some(source_sha256)).map(Admitted::Core1)
        }
        mori_core::stage::LANGUAGE_2 => {
            let staged = mori_core::stage::load(source).map_err(CompileError::Core)?;
            Ok(Admitted::Staged2(StagedAdmission::new(staged, source_sha256)))
        }
        other => Err(CompileError::Profile(other.to_string())),
    }
}

/// Admit an in-memory `/1` Program through the same Core checks.
pub fn admit_program(program: Program) -> Result<AdmittedCore1, CompileError> {
    admit_checked(program, None)
}

fn admit_checked(program: Program, source_sha256: Option<Digest32>) -> Result<AdmittedCore1, CompileError> {
    mori_core::stage::require_core1(&program).map_err(CompileError::Core)?;
    mori_core::validate(&program).map_err(CompileError::Core)?;
    let program_hash = identity::program_hash(&program)?;
    let identity = ProgramIdentity {
        language: program.language.clone(),
        semantics: program.semantics.clone(),
        program_hash,
        source_sha256,
    };
    Ok(AdmittedCore1 { program, identity })
}

//! UNADOPTED candidate compiler from an admitted current-Core `moriarty/1` typed
//! `Program` to an arkworks 0.4 R1CS relation, one relation per (program, action).
//!
//! Source only: nothing in this crate has been compiled, tested or run.
//!
//! Pipeline, the same for every admitted program:
//!
//! 1. [`frontend`]: actual `mori_core::language` routing, then `mori_core::parse` +
//!    `validate` + `stage::require_core1` for `/1`, or `mori_core::stage::load` for
//!    `/2`. `/2` is admitted and then refused by [`compile_source`] with a
//!    [`staged::StagedLoweringPlan`] built from the real stage plan.
//! 2. [`plan`]: a static analysis of the selected action over the typed IR: name
//!    environment, represented balance cells, the program duty registry, ordered effect
//!    shapes and the logical-work constant `W`. Unsupported constructs refuse here.
//! 3. [`statement`]: the typed statement layout (header constants and body slots) and
//!    its exact field encoding.
//! 4. `lower`: constraint lowering of every statement and every expression node with
//!    the exact-integer gadgets. Nothing is recognised by program name or hash.
//! 5. [`circuit`]: entry wires, lowering, cap and accounting constraints, and binding of
//!    every slot through the UNADOPTED [`adapter`] boundary.
//!
//! Separation of witness proposal and acceptance: [`witness`] may call the current
//! Core reference (`simulate`/`simulate_metered`) to *propose* the claimed transition.
//! The circuit recomputes every internal wire from the claimed pre-state and inputs and
//! constrains it against the claimed post-state and effects; no reference result is a
//! Boolean the circuit trusts. A wrong proposal yields an unsatisfied constraint system,
//! not an accepted claim.
//!
//! P3S1 successor (PROPOSED, unreviewed, never compiled or run): adds the
//! `SettlementHashV2` adapter ([`abi2`]) with an in-circuit BLAKE2b-256 ([`blake2b`]) that
//! binds the MRG16-PVC ABI v2 statement to two public inputs. Every inherited source
//! path, constraint and test is unchanged except the adapter dispatch in `circuit.rs`.
//!
//! P3S1-R1 successor (PROPOSED, unreviewed, never compiled or run): the compiler build
//! identity is byte-derived from embedded source bytes ([`build_identity`]); a
//! caller-supplied `CompilerBuild` other than the embedded one is refused. `coverage.rs`
//! carries the R-01 wording (byte copy of the evidence-repair resume candidate's file).
//! No constraint-generating code changed.
#![forbid(unsafe_code)]

pub mod abi2;
pub mod adapter;
pub mod blake2b;
pub mod build_identity;
pub mod circuit;
pub mod coverage;
pub mod error;
pub mod frontend;
mod gadgets;
#[cfg(feature = "groth16")]
