impl ActionPlan {
    pub fn cell_index(&self, asset: &AssetId, account: &str) -> Option<usize> {
        self.cells.iter().position(|c| &c.asset == asset && c.account == account)
    }
    pub fn duty_index(&self, name: &str) -> Option<usize> {
        self.duties.iter().position(|d| d.name == name)
    }
    pub fn state_index(&self, name: &str) -> Option<usize> {
        self.states.iter().position(|s| s.name == name)
    }
}

/// Root expression of a statement, as charged by the logical meter.
pub(crate) fn statement_root(statement: &Statement) -> ExprId {
    match statement {
        Statement::Await { guard, .. } => *guard,
        Statement::Let { value, .. } | Statement::Next { value, .. } | Statement::Emit { value, .. } => *value,
        Statement::Requires { predicate } | Statement::Ensures { predicate } => *predicate,
        Statement::Transfer { amount, .. }
        | Statement::Fee { amount, .. }
        | Statement::Liability { amount, .. }
        | Statement::Discharge { amount, .. } => *amount,
    }
}

/// Distinct nodes reachable from `root` (the per-statement cache charges each once).
pub(crate) fn reachable(program: &Program, root: ExprId) -> Result<BTreeSet<ExprId>, CompileError> {
    let mut seen = BTreeSet::new();
    let mut pending = vec![root];
    while let Some(id) = pending.pop() {
        let node = program.expressions.get(usize::from(id)).ok_or_else(|| CompileError::Bound(format!("expression {id} out of range")))?;
        if !seen.insert(id) {
            continue;
        }
        match node {
            Expr::Binary { lhs, rhs, .. } => {
                pending.push(*lhs);
                pending.push(*rhs);
            }
            Expr::Not { value } => pending.push(*value),
            Expr::LiabilityPresent { .. } | Expr::LiabilityAmount { .. } | Expr::Literal { .. } | Expr::Name { .. } => {}
        }
    }
    Ok(seen)
}

/// Successful logical cost of one statement: one dispatch plus its distinct nodes.
pub(crate) fn statement_cost(program: &Program, statement: &Statement) -> Result<u128, CompileError> {
    Ok(reachable(program, statement_root(statement))?.len() as u128 + 1)
}

/// Type of an expression in a validated program under `env` (Core already proved
/// well-typedness; this only recovers types for slot shapes).
pub(crate) fn infer(program: &Program, id: ExprId, env: &BTreeMap<String, Type>) -> Result<Type, CompileError> {
    let node = program.expressions.get(usize::from(id)).ok_or_else(|| CompileError::Bound(format!("expression {id} out of range")))?;
    Ok(match node {
        Expr::LiabilityPresent { .. } => Type::Bool,
        Expr::LiabilityAmount { .. } => Type::UInt,
        Expr::Literal { value } => value.ty(),
        Expr::Name { name } => *env.get(name).ok_or_else(|| CompileError::Bound(format!("unbound name {name:?} after validation")))?,
        Expr::Not { .. } => Type::Bool,
        Expr::Binary { op, .. } => match op {
            mori_core::BinaryOp::Add | mori_core::BinaryOp::Sub | mori_core::BinaryOp::Mul => Type::UInt,
            mori_core::BinaryOp::Eq
            | mori_core::BinaryOp::Ne
            | mori_core::BinaryOp::Lt
            | mori_core::BinaryOp::Le
            | mori_core::BinaryOp::Gt
            | mori_core::BinaryOp::Ge
            | mori_core::BinaryOp::And
            | mori_core::BinaryOp::Or => Type::Bool,
        },
    })
}

fn asset_by_name<'a>(program: &'a Program, name: &str) -> Result<&'a AssetId, CompileError> {
    program
        .assets
        .iter()
        .find(|a| a.name == name)
        .map(|a| &a.identity)
        .ok_or_else(|| CompileError::Option(format!("unknown asset {name:?}")))
}

struct Registry {
    by_name: BTreeMap<String, (String, AssetId, String, String)>,
}

/// Source-introduced duty identities over every action. Conflicting identities make
/// every Core `simulate` refuse in `scenario_snapshot` (`runtime.rs:500-527,629`).
fn registry(program: &Program) -> Result<Registry, CompileError> {
    let mut by_name: BTreeMap<String, (String, AssetId, String, String)> = BTreeMap::new();
    for statement in program.actions.iter().flat_map(|a| &a.statements) {
        if let Statement::Liability { name, asset, debtor, creditor, .. } = statement {
            let identity = (asset.clone(), asset_by_name(program, asset)?.clone(), debtor.clone(), creditor.clone());
            if let Some(previous) = by_name.insert(name.clone(), identity.clone()) {
                if previous.1 != identity.1 || previous.2 != identity.2 || previous.3 != identity.3 {
                    return Err(CompileError::StaticFailure {
                        scope: "program".into(),
                        reason: format!("conflicting source liability identity for {name:?}; every Core simulate refuses"),
                    });
                }
            }
        }
    }
    Ok(Registry { by_name })
}

/// Builds the plan for `options.action`.
pub fn plan_action(program: &Program, options: &CompileOptions) -> Result<ActionPlan, CompileError> {
    let action_index = program
        .actions
        .iter()
        .position(|a| a.name == options.action)
        .ok_or_else(|| CompileError::UnknownAction(options.action.clone()))?;
    let action = &program.actions[action_index];
    let action_index = u16::try_from(action_index).map_err(|_| CompileError::Bound("action index exceeds u16".into()))?;
    let statement_count =
        u16::try_from(action.statements.len()).map_err(|_| CompileError::Bound("statement count exceeds u16".into()))?;

    let inputs: Vec<NamedType> = action.inputs.iter().map(|i| NamedType { name: i.name.clone(), ty: i.ty }).collect();
    let mut states: Vec<NamedType> = program.states.iter().map(|s| NamedType { name: s.name.clone(), ty: s.ty }).collect();
    states.sort_by(|a, b| a.name.cmp(&b.name));

    let registry = registry(program)?;

    // Cells: touched by this action, then optional preserved frame cells.
    let mut cells: BTreeMap<(AssetId, String), (String, bool)> = BTreeMap::new();
    let mut liability_statements = 0usize;
    let mut touched_duties: BTreeSet<String> = BTreeSet::new();
    for statement in &action.statements {
        match statement {
            Statement::Transfer { asset, from, to, .. } | Statement::Fee { asset, from, to, .. } => {
                let id = asset_by_name(program, asset)?.clone();
                cells.insert((id.clone(), from.clone()), (asset.clone(), true));
                cells.insert((id, to.clone()), (asset.clone(), true));
            }
            Statement::Liability { name, .. } => {
                liability_statements += 1;
                touched_duties.insert(name.clone());
            }
            Statement::Discharge { name, .. } => {
                touched_duties.insert(name.clone());
            }
            Statement::Await { .. } => {
                return Err(CompileError::Unsupported {
                    construct: "Statement::Await",
                    reason: "Await is moriarty-core/2 only; /1 admission refuses it".into(),
                });
            }
            Statement::Let { .. }
            | Statement::Requires { .. }
            | Statement::Ensures { .. }
            | Statement::Next { .. }
            | Statement::Emit { .. } => {}
        }
        for id in reachable(program, statement_root(statement))? {
            if let Expr::LiabilityPresent { name } | Expr::LiabilityAmount { name } = &program.expressions[usize::from(id)] {
                touched_duties.insert(name.clone());
            }
        }
    }
    if let FrameCells::Include(extra) = &options.frame {
        for cell in extra {
            if cell.account.is_empty() || cell.account.len() > 1024 {
                return Err(CompileError::Option("frame cell account must contain 1..1024 bytes".into()));
            }
            let id = asset_by_name(program, &cell.asset)?.clone();
            cells.entry((id, cell.account.clone())).or_insert((cell.asset.clone(), false));
        }
    }
    let cells: Vec<CellKey> = cells
        .into_iter()
        .map(|((asset, account), (asset_name, touched))| CellKey { asset_name, asset, account, touched })
        .collect();

    // Duties: the whole source registry. A duty this action touches or reads without
    // a source introduction would need a dynamic identity cell: refused (first slice).
    for name in &touched_duties {
        if !registry.by_name.contains_key(name) {
            return Err(CompileError::Unsupported {
                construct: "external duty",
                reason: format!(
                    "duty {name:?} has no source Liability introduction; its identity would be prover data. \
                     First slice represents only source-fixed duty identities."
                ),
            });
        }
    }
    let duties: Vec<DutyKey> = registry
        .by_name
        .iter()
        .map(|(name, (asset_name, asset, debtor, creditor))| DutyKey {
            name: name.clone(),
            asset_name: asset_name.clone(),
            asset: asset.clone(),
            debtor: debtor.clone(),
            creditor: creditor.clone(),
            touched: touched_duties.contains(name),
        })
        .collect();

    // Effect shapes and logical schedule, statement by statement.
    let mut env: BTreeMap<String, Type> = program.states.iter().map(|s| (s.name.clone(), s.ty)).collect();
    for input in &action.inputs {
        env.insert(input.name.clone(), input.ty);
    }
    let cell_at = |asset: &AssetId, account: &str| -> Result<usize, CompileError> {
        cells
            .iter()
            .position(|c| &c.asset == asset && c.account == account)
            .ok_or_else(|| CompileError::Bound("touched cell missing from plan".into()))
    };
    let duty_at = |name: &str| -> Result<usize, CompileError> {
        duties.iter().position(|d| d.name == name).ok_or_else(|| CompileError::Bound("duty missing from plan".into()))
    };
    let mut effects = Vec::new();
    let mut schedule = Vec::with_capacity(action.statements.len());
    let mut total: u128 = 0;
    for (index, statement) in action.statements.iter().enumerate() {
        let ordinal = index as u16;
        let cost = statement_cost(program, statement)?;
        total = total.checked_add(cost).ok_or_else(|| CompileError::Bound("logical work exceeds u128".into()))?;
        schedule.push(UInt(cost));
        match statement {
            Statement::Let { name, value } => {
                let ty = infer(program, *value, &env)?;
                env.insert(name.clone(), ty);
            }
            Statement::Next { state, .. } => {
                let ty = *env.get(state).ok_or_else(|| CompileError::Bound(format!("unknown state {state:?}")))?;
                effects.push(EffectShape::State { statement: ordinal, name: state.clone(), ty });
            }
            Statement::Emit { name, value } => {
                let ty = infer(program, *value, &env)?;
                effects.push(EffectShape::Emit { statement: ordinal, name: name.clone(), ty });
            }
            Statement::Transfer { asset, from, to, .. } | Statement::Fee { asset, from, to, .. } => {
                let id = asset_by_name(program, asset)?.clone();
                let from_cell = cell_at(&id, from)?;
                let to_cell = cell_at(&id, to)?;
                effects.push(if matches!(statement, Statement::Fee { .. }) {
                    EffectShape::Fee { statement: ordinal, asset: id, from: from.clone(), to: to.clone(), from_cell, to_cell }
                } else {
                    EffectShape::Transfer { statement: ordinal, asset: id, from: from.clone(), to: to.clone(), from_cell, to_cell }
                });
            }
            Statement::Liability { name, .. } => {
                effects.push(EffectShape::Liability { statement: ordinal, duty: duty_at(name)?, name: name.clone(), origin: DutyOrigin::Accrue });
            }
            Statement::Discharge { name, .. } => {
                effects.push(EffectShape::Liability { statement: ordinal, duty: duty_at(name)?, name: name.clone(), origin: DutyOrigin::Discharge });
            }
            Statement::Requires { .. } | Statement::Ensures { .. } => {}
            Statement::Await { .. } => unreachable!("refused above"),
        }
    }
    let debit_cells: Vec<usize> =
        effects.iter().filter_map(EffectShape::debit_cell).collect::<BTreeSet<_>>().into_iter().collect();

    // Core refuses scenarios whose trace product exceeds MAX_TRACE_CELLS
    // (runtime.rs:540-547). Counting every represented duty as present is the
    // conservative bound used by the Cardano layout as well (layout.rs:47-57). Rows
    // outside the represented snapshot are a target premise (see adapter.rs).
    let records = program.states.len() + cells.len() + duties.len() + liability_statements + 1;
    let trace = records
        .checked_mul(action.statements.len() + 2)
        .ok_or_else(|| CompileError::Bound("trace product overflow".into()))?;
    if trace > MAX_TRACE_CELLS {
        return Err(CompileError::Bound(format!(
            "represented snapshot needs {trace} trace records, above Core's {MAX_TRACE_CELLS}"
        )));
    }
    if cells.len() > 4096 || duties.len() > 1024 {
        return Err(CompileError::Bound("represented cells exceed Core's 4,096 balances or 1,024 liabilities".into()));
    }

    Ok(ActionPlan {
        action: action.name.clone(),
        action_index,
        statement_count,
        inputs,
        states,
        cells,
        duties,
        effects,
        debit_cells,
        logical_schedule: schedule,
        logical_work: UInt(total),
        cap: options.cap,
        accounting: options.accounting,
        frame: options.frame.clone(),
        represented_trace_cells: trace as u64,
    })
}

//! Constraint lowering of one `/1` action, statement by statement.
//!
//! Follows `runtime.rs:702-912` exactly:
//! - statements run in order; there is no branch, so no path is inactive and no gate
//!   is needed;
//! - each statement lowers every node reachable from its root, `lhs` before `rhs`,
//!   with a fresh per-statement memo (strict evaluation; no short-circuit);
//! - `Next` replaces both the state value and the environment binding;
//! - duty reads see the current duty cell, including present-zero;
//! - Transfer/Fee check the debit before the credit and keep the debit check for a
//!   self-transfer;
//! - Liability accrues into the current cell and marks it present; Discharge requires
//!   presence and keeps a present-zero cell.
use crate::gadgets::{self, BoolW, CVal, GadgetError, UIntW};
use crate::plan::ActionPlan;
use crate::r1cs::Cs;
use ark_ff::PrimeField;
use mori_core::{BinaryOp, Expr, ExprId, Program, Statement, UInt, Value};
use std::collections::BTreeMap;

#[derive(Debug)]
pub(crate) enum LowerError {
    Gadget { scope: String, error: GadgetError },
    Shape(String),
}

#[derive(Clone, Debug)]
pub(crate) struct DutyW<F: PrimeField> {
    pub present: BoolW<F>,
    pub amount: UIntW<F>,
}

#[derive(Clone, Debug)]
pub(crate) enum EffectW<F: PrimeField> {
    State { before: CVal<F>, after: CVal<F> },
    Amount(UIntW<F>),
    Duty { before: UIntW<F>, after: UIntW<F> },
    Emit(CVal<F>),
}

/// Pre-state and input wires, already bound to their public slots.
pub(crate) struct Entry<F: PrimeField> {
    pub inputs: Vec<CVal<F>>,
    pub states: Vec<CVal<F>>,
    pub cells: Vec<UIntW<F>>,
    pub duties: Vec<DutyW<F>>,
}

/// Post-state and effect wires, to be bound to their public slots.
pub(crate) struct Lowered<F: PrimeField> {
    pub states: Vec<CVal<F>>,
    pub cells: Vec<UIntW<F>>,
    pub duties: Vec<DutyW<F>>,
    pub effects: Vec<EffectW<F>>,
}

struct Ctx<'p, F: PrimeField> {
    program: &'p Program,
    env: BTreeMap<String, CVal<F>>,
    duties: Vec<DutyW<F>>,
    duty_index: BTreeMap<String, usize>,
}

/// Attaches the statement/expression scope to a gadget error. Takes no `Cs` so the
/// gadget call itself can hold the only mutable borrow.
fn gadget<T>(statement: usize, expr: Option<ExprId>, r: Result<T, GadgetError>) -> Result<T, LowerError> {
    r.map_err(|error| LowerError::Gadget {
        scope: match expr {
            Some(e) => format!("s{statement}/e{e}"),
            None => format!("s{statement}"),
        },
        error,
    })
}

fn as_uint<F: PrimeField>(v: CVal<F>) -> Result<UIntW<F>, LowerError> {
    match v {
        CVal::U(u) => Ok(u),
        CVal::B(_) => Err(LowerError::Shape("expected UInt after validation".into())),
    }
}

fn as_bool<F: PrimeField>(v: CVal<F>) -> Result<BoolW<F>, LowerError> {
    match v {
        CVal::B(b) => Ok(b),
        CVal::U(_) => Err(LowerError::Shape("expected Bool after validation".into())),
    }
}

impl<F: PrimeField> Ctx<'_, F> {
    fn duty(&self, name: &str) -> Result<usize, LowerError> {
        self.duty_index.get(name).copied().ok_or_else(|| LowerError::Shape(format!("duty {name:?} absent from plan")))
    }

    /// Lowers node `id` once per statement (memo), operands first, `lhs` before `rhs`.
    fn expr(&self, cs: &mut Cs<F>, statement: usize, id: ExprId, memo: &mut BTreeMap<ExprId, CVal<F>>) -> Result<CVal<F>, LowerError> {
        if let Some(v) = memo.get(&id) {
            return Ok(v.clone());
        }
        let node = self
            .program
            .expressions
            .get(usize::from(id))
            .ok_or_else(|| LowerError::Shape(format!("expression {id} out of range")))?;
        let value = match node {
            Expr::Literal { value } => match value {
                Value::UInt(UInt(n)) => CVal::U(UIntW::constant(*n)),
                Value::Bool(b) => CVal::B(BoolW::constant(*b)),
            },
            Expr::Name { name } => self.env.get(name).cloned().ok_or_else(|| LowerError::Shape(format!("unbound name {name:?}")))?,
            Expr::LiabilityPresent { name } => CVal::B(self.duties[self.duty(name)?].present.clone()),
            Expr::LiabilityAmount { name } => CVal::U(self.duties[self.duty(name)?].amount.clone()),
            Expr::Not { value } => {
                let v = as_bool(self.expr(cs, statement, *value, memo)?)?;
                CVal::B(gadgets::not(&v))
            }
            Expr::Binary { op, lhs, rhs } => {
                let a = self.expr(cs, statement, *lhs, memo)?;
                let b = self.expr(cs, statement, *rhs, memo)?;
                // Statement scope `s{statement}` is already pushed by `lower_action`;
                // witness labels read `s{statement}/e{id}/{role}#n`.
                cs.push(format!("e{id}"));
                let out = self.binary(cs, *op, a, b);
                cs.pop();
                gadget(statement, Some(id), out)?
            }
        };
        memo.insert(id, value.clone());
        Ok(value)
    }

    fn binary(&self, cs: &mut Cs<F>, op: BinaryOp, a: CVal<F>, b: CVal<F>) -> Result<CVal<F>, GadgetError> {
        let shape = |m: &str| GadgetError::Static(format!("operand types differ from validated IR: {m}"));
        Ok(match (op, a, b) {
            (BinaryOp::Add, CVal::U(x), CVal::U(y)) => CVal::U(gadgets::add(cs, "add", &x, &y)?),
            (BinaryOp::Sub, CVal::U(x), CVal::U(y)) => CVal::U(gadgets::sub(cs, "sub", &x, &y)?),
            (BinaryOp::Mul, CVal::U(x), CVal::U(y)) => CVal::U(gadgets::mul(cs, "mul", &x, &y)?),
            (BinaryOp::Lt, CVal::U(x), CVal::U(y)) => CVal::B(gadgets::lt(cs, "lt", &x, &y)?),
            (BinaryOp::Gt, CVal::U(x), CVal::U(y)) => CVal::B(gadgets::lt(cs, "lt", &y, &x)?),
            (BinaryOp::Le, CVal::U(x), CVal::U(y)) => CVal::B(gadgets::not(&gadgets::lt(cs, "lt", &y, &x)?)),
            (BinaryOp::Ge, CVal::U(x), CVal::U(y)) => CVal::B(gadgets::not(&gadgets::lt(cs, "lt", &x, &y)?)),
            (BinaryOp::Eq, CVal::U(x), CVal::U(y)) => CVal::B(gadgets::eq_uint(cs, "eq", &x, &y)?),
            (BinaryOp::Ne, CVal::U(x), CVal::U(y)) => CVal::B(gadgets::not(&gadgets::eq_uint(cs, "eq", &x, &y)?)),
            (BinaryOp::Eq, CVal::B(x), CVal::B(y)) => CVal::B(gadgets::eq_bool(cs, "beq", &x, &y)?),
            (BinaryOp::Ne, CVal::B(x), CVal::B(y)) => CVal::B(gadgets::not(&gadgets::eq_bool(cs, "beq", &x, &y)?)),
            (BinaryOp::And, CVal::B(x), CVal::B(y)) => CVal::B(gadgets::and(cs, "and", &x, &y)?),
            (BinaryOp::Or, CVal::B(x), CVal::B(y)) => CVal::B(gadgets::or(cs, "or", &x, &y)?),
            (op, _, _) => return Err(shape(&format!("{op:?}"))),
        })
    }

    fn root(&self, cs: &mut Cs<F>, statement: usize, id: ExprId) -> Result<CVal<F>, LowerError> {
        let mut memo = BTreeMap::new();
        self.expr(cs, statement, id, &mut memo)
    }
}

/// Lowers the selected action. `entry` wires are the bound pre-state and inputs.
pub(crate) fn lower_action<F: PrimeField>(cs: &mut Cs<F>, program: &Program, plan: &ActionPlan, entry: Entry<F>) -> Result<Lowered<F>, LowerError> {
    let action = program
        .actions
        .get(usize::from(plan.action_index))
        .ok_or_else(|| LowerError::Shape("action index out of range".into()))?;
    if entry.inputs.len() != plan.inputs.len()
        || entry.states.len() != plan.states.len()
        || entry.cells.len() != plan.cells.len()
        || entry.duties.len() != plan.duties.len()
    {
        return Err(LowerError::Shape("entry wires differ from plan".into()));
    }
    let mut env: BTreeMap<String, CVal<F>> = BTreeMap::new();
    for (slot, wire) in plan.states.iter().zip(&entry.states) {
        env.insert(slot.name.clone(), wire.clone());
    }
    for (slot, wire) in plan.inputs.iter().zip(&entry.inputs) {
        env.insert(slot.name.clone(), wire.clone());
    }
    let duty_index: BTreeMap<String, usize> = plan.duties.iter().enumerate().map(|(i, d)| (d.name.clone(), i)).collect();
    let mut ctx = Ctx { program, env, duties: entry.duties, duty_index };
    let mut states = entry.states;
    let mut cells = entry.cells;
    let mut effects = Vec::with_capacity(plan.effects.len());

    for (i, statement) in action.statements.iter().enumerate() {
        let start = cs.num_constraints();
        cs.push(format!("s{i}"));
        let step = lower_statement(cs, &mut ctx, plan, i, statement, &mut states, &mut cells, &mut effects);
        cs.pop();
        step?;
        cs.record(format!("statement {i}"), start);
    }
    if effects.len() != plan.effects.len() {
        return Err(LowerError::Shape("lowered effect count differs from plan".into()));
    }
    Ok(Lowered { states, cells, duties: ctx.duties, effects })
}

#[allow(clippy::too_many_arguments)]
fn lower_statement<F: PrimeField>(
    cs: &mut Cs<F>,
    ctx: &mut Ctx<'_, F>,
    plan: &ActionPlan,
    i: usize,
    statement: &Statement,
    states: &mut [CVal<F>],
    cells: &mut [UIntW<F>],
    effects: &mut Vec<EffectW<F>>,
) -> Result<(), LowerError> {
    match statement {
        Statement::Let { name, value } => {
            let v = ctx.root(cs, i, *value)?;
            ctx.env.insert(name.clone(), v);
        }
        Statement::Requires { predicate } | Statement::Ensures { predicate } => {
            let v = as_bool(ctx.root(cs, i, *predicate)?)?;
            let what = if matches!(statement, Statement::Requires { .. }) { "requires" } else { "ensures" };
            gadget(i, None, gadgets::assert_true(cs, &v, what))?;
        }
        Statement::Next { state, value } => {
            let after = ctx.root(cs, i, *value)?;
            let index = plan.state_index(state).ok_or_else(|| LowerError::Shape(format!("state {state:?} absent")))?;
            let before = std::mem::replace(&mut states[index], after.clone());
            ctx.env.insert(state.clone(), after.clone());
            effects.push(EffectW::State { before, after });
        }
        Statement::Emit { value, .. } => {
            let v = ctx.root(cs, i, *value)?;
            effects.push(EffectW::Emit(v));
        }
        Statement::Transfer { asset, from, to, amount } | Statement::Fee { asset, from, to, amount } => {
            let amt = as_uint(ctx.root(cs, i, *amount)?)?;
            let id = &ctx
                .program
                .assets
                .iter()
                .find(|a| a.name == *asset)
                .ok_or_else(|| LowerError::Shape(format!("asset {asset:?} absent")))?
                .identity;
            let f = plan.cell_index(id, from).ok_or_else(|| LowerError::Shape("debit cell absent".into()))?;
            let t = plan.cell_index(id, to).ok_or_else(|| LowerError::Shape("credit cell absent".into()))?;
            // Debit check first (runtime.rs:685-689), also for a self-transfer.
            let debit = gadget(i, None, gadgets::sub(cs, "debit", &cells[f], &amt))?;
            if f != t {
                let credit = gadget(i, None, gadgets::add(cs, "credit", &cells[t], &amt))?;
                cells[f] = debit;
                cells[t] = credit;
            }
            effects.push(EffectW::Amount(amt));
        }
        Statement::Liability { name, amount, .. } => {
            let amt = as_uint(ctx.root(cs, i, *amount)?)?;
            let d = ctx.duty(name)?;
            // Absent cells carry amount 0 (canonicality enforced at entry), so `before`
            // is the Core `before` in both the present and absent cases.
            let before = ctx.duties[d].amount.clone();
            let after = gadget(i, None, gadgets::add(cs, "accrue", &before, &amt))?;
            ctx.duties[d] = DutyW { present: BoolW::constant(true), amount: after.clone() };
            effects.push(EffectW::Duty { before, after });
        }
        Statement::Discharge { name, amount } => {
            let amt = as_uint(ctx.root(cs, i, *amount)?)?;
            let d = ctx.duty(name)?;
            let present = ctx.duties[d].present.clone();
            gadget(i, None, gadgets::assert_true(cs, &present, "discharged duty presence"))?;
            let before = ctx.duties[d].amount.clone();
            let after = gadget(i, None, gadgets::sub(cs, "discharge", &before, &amt))?;
            ctx.duties[d].amount = after.clone();
            effects.push(EffectW::Duty { before, after });
        }
        Statement::Await { .. } => {
            return Err(LowerError::Shape("Await reached /1 lowering".into()));
        }
    }
    Ok(())
}

language "moriarty/1";
agreement InstallmentInvoice {
  state opened: Bool = false;
  state paid: UInt = 0;
  state marker: UInt = 7;
  asset CASH = { network: "oracle-unit", issuer: "invoice-issuer", reference: "cash", scale: 0 };
  action open(principal: UInt, reserve: UInt) {
    requires not opened;
    ensures paid == 0;
    requires not liability_present("invoice");
    let face = principal + 10;
    let funding = face + reserve;
    transfer(CASH, "buyer", "escrow", funding);
    fee(CASH, "buyer", "fees", 3);
    liability("invoice", CASH, "escrow", "seller", principal);
    liability("invoice", CASH, "escrow", "seller", 10);
    liability("reserve", CASH, "escrow", "buyer", reserve);
    next opened = true;
    ensures liability_amount("invoice") == face and liability_amount("reserve") == reserve;
  }
  action partial(amount: UInt) {
    requires opened and amount > 0;
    let opening = liability_amount("invoice");
    requires amount < opening;
    fee(CASH, "escrow", "fees", 2);
    transfer(CASH, "escrow", "seller", amount);
    discharge("invoice", amount);
    next paid = paid + amount;
    ensures liability_amount("invoice") == opening - amount;
  }
  action finish() {
    requires opened;
    let closing = liability_amount("invoice");
    transfer(CASH, "escrow", "seller", closing);
    discharge("invoice", closing);
    next paid = paid + closing;
    next opened = false;
    ensures liability_present("invoice") and liability_amount("invoice") == 0;
  }
}

language "moriarty/1";
agreement ConditionalReserve {
  state allocated: Bool = false;
  state rounds: UInt = 0;
  state marker: UInt = 77;
  asset A = { network: "oracle-unit", issuer: "reserve-issuer", reference: "A", scale: 0 };
  asset B = { network: "oracle-unit", issuer: "reserve-issuer", reference: "B", scale: 0 };
  action allocate(approved: Bool, units: UInt, quotient: UInt, remainder: UInt) {
    requires approved and not allocated;
    requires remainder < 3;
    requires units == quotient * 3 + remainder;
    requires units >= 3 and quotient not = 0;
    let toAlpha = quotient * 2;
    let toBeta = quotient;
    ensures rounds == 0;
    fee(A, "vault", "fees", 2);
    transfer(A, "vault", "alpha", toAlpha);
    transfer(A, "vault", "beta", toBeta);
    transfer(B, "vault", "alpha", 4);
    liability("allocation_reserve", A, "vault", "owner", remainder);
    liability("rebate", B, "vault", "owner", 6);
    next allocated = true;
    next rounds = rounds + 1;
    ensures liability_amount("allocation_reserve") == remainder;
  }
  action rebate(amount: UInt) {
    requires allocated;
    let prior = liability_amount("rebate");
    requires amount <= prior;
    transfer(B, "vault", "owner", amount);
    discharge("rebate", amount);
    next rounds = rounds + 1;
    ensures liability_amount("rebate") == prior - amount;
    ensures liability_present("allocation_reserve") or false;
  }
}

//! Compilation entry points, the compile-time probe and constraint synthesis.
//!
//! `compile` admits nothing by itself: it takes an [`AdmittedCore1`] (actual Core
//! parse/validate), builds the plan and statement layout, and runs one setup-mode
//! synthesis (the probe) to refuse static failures and to record constraint counts and
//! the R1CS matrix digest. Those numbers exist only after an actual run; this source
//! records none.
//!
//! Synthesis order: entry wires (claimed inputs and pre-state, range-proven), the
//! statement-by-statement lowering, the cap constraint, the accounting summary, then
//! binding of every slot through the adapter. Internal wires are computed from the
//! claimed inputs and pre-state only; claimed post-state and effects enter solely as
//! public values that the binding equates with the computed wires.
use crate::abi2::{self, AbiV2Constants, ContextV2};
use crate::adapter::{AdapterError, BindError, SlotWire, StatementAdapter};
use crate::error::{CompileError, MappingError};
use crate::frontend::{self, Admitted, AdmittedCore1};
use crate::gadgets::{self, BoolW, CVal, GadgetError, UIntW, WideW};
use crate::identity::{self, Digest32, RelationIdentity};
use crate::lower::{self, DutyW, EffectW, Entry, LowerError};
use crate::plan::{self, AccountingBinding, ActionPlan, CapBinding, CompileOptions};
use crate::r1cs::{Cs, Lc, RegionCount, Tamper};
use crate::statement::{BodyValues, EffectRole, HeaderField, SlotKind, StatementLayout, TransitionValues};
use ark_ff::{BigInteger, PrimeField};
use ark_relations::r1cs::{
    ConstraintSynthesizer, ConstraintSystem, ConstraintSystemRef, OptimizationGoal, SynthesisError, SynthesisMode,
};
use mori_core::{Program, Type, UInt, Value};
use serde::Serialize;

/// Facts recorded by the compile-time probe synthesis. Only an actual run fills them.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct ProbeReport {
    pub field_modulus_bits: u32,
    /// Little-endian hex of the scalar modulus the relation was probed in.
    pub field_modulus_le_hex: String,
    pub constraints: usize,
    /// Includes arkworks' constant-one instance variable.
    pub instance_variables: usize,
    pub witness_variables: usize,
    pub regions: Vec<RegionCount>,
    /// SHA-256 of the finalized A/B/C matrices (format `mori-r1cs-matrices/1`), under
    /// `OptimizationGoal::Constraints` as ark-groth16 0.4 setup uses (UNVERIFIED-LIB).
    pub r1cs_sha256: Digest32,
}

/// Facts from one synthesis (tests read `overrides_used`).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SynthesisReport {
    pub regions: Vec<RegionCount>,
    pub overrides_used: usize,
    pub constraints: usize,
}

/// One compiled relation: an admitted Program, one action, explicit options.
#[derive(Debug, Clone)]
pub struct CompiledRelation {
    admitted: AdmittedCore1,
    options: CompileOptions,
    plan: ActionPlan,
    layout: StatementLayout,
    identity: RelationIdentity,
    adapter: StatementAdapter,
    /// ABI v2 constants (P3S1); present exactly for [`StatementAdapter::SettlementHashV2`].
    abi2: Option<AbiV2Constants>,
    probe: ProbeReport,
}

/// A claimed transition and its exact public encoding.
#[derive(Debug, Clone)]
pub struct Assignment<F: PrimeField> {
    pub values: TransitionValues,
    /// Public inputs in instance order. Tests may mutate it to play a hostile claimant.
    pub public: Vec<F>,
}

impl CompiledRelation {
    pub fn program(&self) -> &Program {
        self.admitted.program()
    }
    pub fn admitted(&self) -> &AdmittedCore1 {
        &self.admitted
    }
    pub fn options(&self) -> &CompileOptions {
        &self.options
    }
    pub fn plan(&self) -> &ActionPlan {
        &self.plan
    }
    pub fn layout(&self) -> &StatementLayout {
        &self.layout
    }
    pub fn identity(&self) -> &RelationIdentity {
        &self.identity
    }
    pub fn adapter(&self) -> StatementAdapter {
        self.adapter
    }
    pub fn probe(&self) -> &ProbeReport {
        &self.probe
    }
    pub fn abi2(&self) -> Option<&AbiV2Constants> {
        self.abi2.as_ref()
    }

    /// P3S1: the ABI v2 statement of a claimed transition in a context. Checks shape and
    /// types only; acceptance is the constraint system's.
    pub fn statement_v2(&self, values: &TransitionValues, context: &ContextV2) -> Result<Vec<u8>, MappingError> {
        let consts = self
            .abi2
            .as_ref()
            .ok_or(MappingError::Adapter(AdapterError::Unadopted("statement_v2 needs the SettlementHashV2 adapter")))?;
        crate::statement::check_values(&self.plan, values)?;
        let body = abi2::body_bytes(&self.layout, &self.plan, values)?;
        abi2::statement_bytes(consts, context, &body)
    }

    /// P3S1: the two ABI v2 public inputs of a claimed transition in a context.
    pub fn public_inputs_v2<F: PrimeField>(&self, values: &TransitionValues, context: &ContextV2) -> Result<Vec<F>, MappingError> {
        self.check_field::<F>().map_err(MappingError::Field)?;
        Ok(abi2::public_inputs::<F>(&self.statement_v2(values, context)?))
    }

    /// P3S1: an ABI v2 assignment (public = the two digest halves).
    pub fn assignment_v2<F: PrimeField>(&self, values: TransitionValues, context: &ContextV2) -> Result<Assignment<F>, MappingError> {
        let public = self.public_inputs_v2::<F>(&values, context)?;
        Ok(Assignment { values, public })
    }

    /// P3S1: an ABI v2 circuit for proving (assignment and context) or setup (neither).
    pub fn circuit_v2<F: PrimeField>(
        &self,
        assignment: Option<Assignment<F>>,
        context: Option<ContextV2>,
        tamper: Tamper<F>,
    ) -> Result<TransitionCircuit<'_, F>, CompileError> {
        self.check_field::<F>().map_err(CompileError::Field)?;
        if self.adapter != StatementAdapter::SettlementHashV2 {
            return Err(CompileError::Option("circuit_v2 needs the SettlementHashV2 adapter".into()));
        }
        if assignment.is_some() != context.is_some() {
            return Err(CompileError::Option("SettlementHashV2 proving needs both an assignment and a ContextV2".into()));
        }
        if let Some(a) = &assignment {
            self.check_assignment_lengths(a)?;
        }
        Ok(TransitionCircuit { relation: self, assignment, context, tamper })
    }

    /// The public inputs a verifier supplies for `values`.
    pub fn public_inputs<F: PrimeField>(&self, values: &TransitionValues) -> Result<Vec<F>, MappingError> {
        self.check_field::<F>().map_err(MappingError::Field)?;
        self.adapter.public_inputs(&self.layout, &self.plan, values)
    }

    /// Encodes a claimed transition. This checks shape and types only; acceptance is
    /// the constraint system's.
    pub fn assignment<F: PrimeField>(&self, values: TransitionValues) -> Result<Assignment<F>, MappingError> {
        let public = self.public_inputs::<F>(&values)?;
        Ok(Assignment { values, public })
    }

    /// A circuit for proving (`Some`) or setup (`None`).
    pub fn circuit<F: PrimeField>(&self, assignment: Option<Assignment<F>>, tamper: Tamper<F>) -> Result<TransitionCircuit<'_, F>, CompileError> {
        self.check_field::<F>().map_err(CompileError::Field)?;
        if self.adapter == StatementAdapter::SettlementHashV2 && assignment.is_some() {
            return Err(CompileError::Option("SettlementHashV2 proving needs circuit_v2 with a ContextV2".into()));
        }
        if let Some(a) = &assignment {
            self.check_assignment_lengths(a)?;
        }
        Ok(TransitionCircuit { relation: self, assignment, context: None, tamper })
    }

    /// Refuses an assignment whose vectors do not have this relation's lengths (review
    /// F-12). `Assignment` fields are public, so a hand-built value could otherwise make
    /// synthesis index out of bounds and panic. Lengths only: value types, absent-duty
    /// canonicality and every value relation stay with the constraint system, so this
    /// adds no constraint and decides no well-shaped claim.
    fn check_assignment_lengths<F: PrimeField>(&self, a: &Assignment<F>) -> Result<(), CompileError> {
        let plan = &self.plan;
        let body = |b: &BodyValues| -> bool {
            b.states.len() == plan.states.len() && b.cells.len() == plan.cells.len() && b.duties.len() == plan.duties.len()
        };
        let checks = [
            ("inputs", a.values.inputs.len() == plan.inputs.len()),
            ("pre body", body(&a.values.pre)),
            ("post body", body(&a.values.post)),
            ("effects", a.values.effects.len() == plan.effects.len()),
            ("public inputs", self.adapter.public_input_count(&self.layout).is_ok_and(|n| a.public.len() == n)),
        ];
        match checks.iter().find(|(_, ok)| !*ok) {
            Some((what, _)) => Err(CompileError::AssignmentShape(format!("{what} length differs from the relation"))),
            None => Ok(()),
        }
    }

    fn check_field<F: PrimeField>(&self) -> Result<(), String> {
        let modulus = hex_le(&F::MODULUS.to_bytes_le());
        if modulus != self.probe.field_modulus_le_hex {
            return Err("circuit field differs from the field the relation was compiled and probed in".into());
        }
        Ok(())
    }
}

fn hex_le(bytes: &[u8]) -> String {
    mori_core::intent::hex(bytes)
}

/// Compiles one action of an admitted `/1` Program over the scalar field `F`.
pub fn compile<F: PrimeField>(admitted: AdmittedCore1, options: CompileOptions, adapter: StatementAdapter) -> Result<CompiledRelation, CompileError> {
    if F::MODULUS_BIT_SIZE < crate::MIN_MODULUS_BITS {
        return Err(CompileError::Field(format!(
            "scalar field has {} bits; the exact-integer gadgets need at least {}",
            F::MODULUS_BIT_SIZE,
            crate::MIN_MODULUS_BITS
        )));
    }
    let build = options.compiler.checked()?;
    adapter.admits(admitted.program()).map_err(CompileError::Adapter)?;
    if adapter == StatementAdapter::SettlementHashV2 {
        abi2::options_ok(&options)?;
    }
    let plan = plan::plan_action(admitted.program(), &options)?;
    let layout = StatementLayout::build(admitted.identity(), &plan, build)?;
    let program_identity = admitted.identity().clone();
    let identity = RelationIdentity {
        relation_format: crate::RELATION_FORMAT.into(),
        relation_version: crate::RELATION_VERSION,
        language: program_identity.language.clone(),
        semantics: program_identity.semantics.clone(),
        logical_cost_profile: mori_core::LOGICAL_COST_PROFILE.into(),
        profile_digest: layout.header.profile_digest,
        program_hash: program_identity.program_hash,
        source_sha256: program_identity.source_sha256,
        action: plan.action.clone(),
        action_index: plan.action_index,
        shape_digest: layout.header.shape_digest,
        compiler_build: build,
        compiler_build_digest: layout.header.compiler_build_digest,
        adapter,
        logical_work: plan.logical_work,
    };
    let placeholder = ProbeReport {
        field_modulus_bits: F::MODULUS_BIT_SIZE,
        field_modulus_le_hex: hex_le(&F::MODULUS.to_bytes_le()),
        constraints: 0,
        instance_variables: 0,
        witness_variables: 0,
        regions: Vec::new(),
        r1cs_sha256: Digest32([0; 32]),
    };
    let abi2 = if adapter == StatementAdapter::SettlementHashV2 {
        Some(abi2::constants(admitted.program(), &plan, &layout, identity.digest()?.0)?)
    } else {
        None
    };
    let mut relation = CompiledRelation { admitted, options, plan, layout, identity, adapter, abi2, probe: placeholder };
    relation.probe = probe::<F>(&relation)?;
    Ok(relation)
}

/// Routes source by its declared profile and compiles `/1`. `/2` is admitted by the
/// actual stage loader and then refused with its staged lowering plan.
pub fn compile_source<F: PrimeField>(source: &str, options: CompileOptions, adapter: StatementAdapter) -> Result<CompiledRelation, CompileError> {
    match frontend::admit_source(source)? {
        Admitted::Core1(admitted) => compile::<F>(admitted, options, adapter),
        Admitted::Staged2(staged) => Err(CompileError::StagedNotLowered(Box::new(staged.lowering_plan()?))),
    }
}

/// Setup-mode synthesis: refuses static failures and records counts and the matrix
/// digest. The same function synthesizes for proving, so the structure is identical.
fn probe<F: PrimeField>(relation: &CompiledRelation) -> Result<ProbeReport, CompileError> {
    let cs = ConstraintSystem::<F>::new_ref();
    cs.set_optimization_goal(OptimizationGoal::Constraints);
    cs.set_mode(SynthesisMode::Setup);
    let report = synthesize(relation, None, None, Tamper::none(), cs.clone()).map_err(SynthFailure::into_compile_error)?;
    cs.finalize();
    let matrices = cs.to_matrices().ok_or_else(|| CompileError::Synthesis("constraint matrices were not constructed".into()))?;
    let mut bytes = b"mori-r1cs-matrices/1\0".to_vec();
    for n in [matrices.num_instance_variables, matrices.num_witness_variables, matrices.num_constraints] {
        bytes.extend_from_slice(&(n as u64).to_le_bytes());
    }
    for matrix in [&matrices.a, &matrices.b, &matrices.c] {
        bytes.extend_from_slice(&(matrix.len() as u64).to_le_bytes());
        for row in matrix {
            bytes.extend_from_slice(&(row.len() as u64).to_le_bytes());
            for (coefficient, index) in row {
                bytes.extend_from_slice(&(*index as u64).to_le_bytes());
                let le = coefficient.into_bigint().to_bytes_le();
                bytes.extend_from_slice(&(le.len() as u64).to_le_bytes());
                bytes.extend_from_slice(&le);
            }
        }
    }
    Ok(ProbeReport {
        field_modulus_bits: F::MODULUS_BIT_SIZE,
        field_modulus_le_hex: hex_le(&F::MODULUS.to_bytes_le()),
        constraints: matrices.num_constraints,
        instance_variables: matrices.num_instance_variables,
        witness_variables: matrices.num_witness_variables,
        regions: report.regions,
        r1cs_sha256: identity::digest_bytes(&bytes),
    })
}

/// The circuit for one claimed transition (or for setup when `assignment` is `None`).
pub struct TransitionCircuit<'r, F: PrimeField> {
    relation: &'r CompiledRelation,
    assignment: Option<Assignment<F>>,
    /// ABI v2 context (P3S1); `None` for the other adapters and in setup mode.
    context: Option<ContextV2>,
    tamper: Tamper<F>,
}

impl<F: PrimeField> TransitionCircuit<'_, F> {
    /// Synthesizes into `cs` and reports regions and tamper hits.
    pub fn synthesize_into(self, cs: ConstraintSystemRef<F>) -> Result<SynthesisReport, SynthesisError> {
        synthesize(self.relation, self.assignment.as_ref(), self.context.as_ref(), self.tamper, cs).map_err(SynthFailure::into_synthesis_error)
    }
}

impl<F: PrimeField> ConstraintSynthesizer<F> for TransitionCircuit<'_, F> {
    fn generate_constraints(self, cs: ConstraintSystemRef<F>) -> Result<(), SynthesisError> {
        self.synthesize_into(cs).map(|_| ())
    }
}

enum SynthFailure {
    Synthesis(SynthesisError),
    Static { scope: String, reason: String },
    Shape(String),
    Adapter(AdapterError),
}

impl SynthFailure {
    fn into_compile_error(self) -> CompileError {
        match self {
            Self::Synthesis(e) => CompileError::Synthesis(e.to_string()),
            Self::Static { scope, reason } => CompileError::StaticFailure { scope, reason },
            Self::Shape(m) => CompileError::Synthesis(format!("internal shape invariant: {m}")),
            Self::Adapter(a) => CompileError::Adapter(a),
        }
    }
    /// After a successful compile probe only `Synthesis` can occur (structure does not
    /// depend on values). The others are internal invariant failures; arkworks 0.4 has
    /// no general variant, so they surface as `Unsatisfiable` and never as success.
    fn into_synthesis_error(self) -> SynthesisError {
        match self {
            Self::Synthesis(e) => e,
            Self::Static { .. } | Self::Shape(_) | Self::Adapter(_) => SynthesisError::Unsatisfiable,
        }
    }
}

impl From<SynthesisError> for SynthFailure {
    fn from(e: SynthesisError) -> Self {
        Self::Synthesis(e)
    }
}

impl From<GadgetError> for SynthFailure {
    fn from(e: GadgetError) -> Self {
        match e {
            GadgetError::Synthesis(s) => Self::Synthesis(s),
            GadgetError::Static(reason) => Self::Static { scope: "statement wiring".into(), reason },
        }
    }
}

impl From<LowerError> for SynthFailure {
    fn from(e: LowerError) -> Self {
        match e {
            LowerError::Gadget { error: GadgetError::Synthesis(s), .. } => Self::Synthesis(s),
            LowerError::Gadget { scope, error: GadgetError::Static(reason) } => Self::Static { scope, reason },
            LowerError::Shape(m) => Self::Shape(m),
        }
    }
}

impl From<BindError> for SynthFailure {
    fn from(e: BindError) -> Self {
        match e {
            BindError::Synthesis(s) => Self::Synthesis(s),
            BindError::Adapter(a) => Self::Adapter(a),
        }
    }
}

fn uint_of(v: &Value) -> u128 {
    match v {
        Value::UInt(UInt(n)) => *n,
        Value::Bool(_) => 0,
    }
}

fn bool_of(v: &Value) -> bool {
    matches!(v, Value::Bool(true))
}

/// Range-proven entry wire for a claimed value of type `ty`.
fn alloc_value<F: PrimeField>(cs: &mut Cs<F>, role: &str, ty: Type, v: Option<&Value>) -> Result<CVal<F>, GadgetError> {
    Ok(match ty {
        Type::UInt => CVal::U(gadgets::alloc_uint(cs, role, v.map(uint_of))?),
        Type::Bool => CVal::B(gadgets::alloc_bool(cs, role, v.map(bool_of))?),
    })
}

fn cval_wire<F: PrimeField>(v: &CVal<F>) -> SlotWire<F> {
    match v {
        CVal::U(u) => SlotWire::U(u.clone()),
        CVal::B(b) => SlotWire::B(b.clone()),
    }
}

fn synthesize<F: PrimeField>(
    relation: &CompiledRelation,
    assignment: Option<&Assignment<F>>,
    context: Option<&ContextV2>,
    tamper: Tamper<F>,
    cs_ref: ConstraintSystemRef<F>,
) -> Result<SynthesisReport, SynthFailure> {
    let plan = &relation.plan;
    let layout = &relation.layout;
    let program = relation.admitted.program();
    let mut cs = Cs::new(cs_ref, tamper);
    if cs.is_setup() != assignment.is_none() {
        return Err(SynthFailure::Shape("an assignment is required exactly when not in setup mode".into()));
    }
    let values = assignment.map(|a| &a.values);

    // Entry: claimed inputs and pre-state, each range-proven. Absent duties are
    // canonical: `(1 - present) * amount = 0`.
    let start = cs.num_constraints();
    cs.push("entry".into());
    let mut inputs = Vec::with_capacity(plan.inputs.len());
    for (i, slot) in plan.inputs.iter().enumerate() {
        inputs.push(alloc_value(&mut cs, &format!("input{i}"), slot.ty, values.map(|v| &v.inputs[i]))?);
    }
    let mut states = Vec::with_capacity(plan.states.len());
    for (i, slot) in plan.states.iter().enumerate() {
        states.push(alloc_value(&mut cs, &format!("state{i}"), slot.ty, values.map(|v| &v.pre.states[i]))?);
    }
    let mut cells = Vec::with_capacity(plan.cells.len());
    for i in 0..plan.cells.len() {
        cells.push(gadgets::alloc_uint(&mut cs, &format!("cell{i}"), values.map(|v| v.pre.cells[i].0))?);
    }
    let mut duties = Vec::with_capacity(plan.duties.len());
    for i in 0..plan.duties.len() {
        let claimed = values.map(|v| v.pre.duties[i]);
        let present = gadgets::alloc_bool(&mut cs, &format!("duty{i}.present"), claimed.map(|d| d.present))?;
        let amount = gadgets::alloc_uint(&mut cs, &format!("duty{i}.amount"), claimed.map(|d| d.amount.0))?;
        cs.enforce(Lc::one().minus(&present.lc), amount.lc(), Lc::zero())?;
        duties.push(DutyW { present, amount });
    }
    cs.pop();
    cs.record("entry".into(), start);

    // Lowering of every statement (records one region per statement).
    let entry = Entry { inputs: inputs.clone(), states: states.clone(), cells: cells.clone(), duties: duties.clone() };
    let lowered = lower::lower_action(&mut cs, program, plan, entry)?;

    // Cap: `W + slack = cap` with `slack` range-proven, i.e. `W <= cap`.
    let cap = if plan.cap == CapBinding::PublicCap {
        let start = cs.num_constraints();
        cs.push("cap".into());
        let cap = gadgets::alloc_uint(&mut cs, "cap", values.and_then(|v| v.cap).map(|c| c.0))?;
        gadgets::sub(&mut cs, "slack", &cap, &UIntW::constant(plan.logical_work.0))?;
        cs.pop();
        cs.record("cap".into(), start);
        Some(cap)
    } else {
        None
    };

    // Accounting summary from the lowered effect wires.
    let mut summary: Vec<(usize, WideW<F>, WideW<F>)> = Vec::new();
    if plan.accounting == AccountingBinding::GrossDebitAndFees {
        let start = cs.num_constraints();
        cs.push("accounting".into());
        for &cell in &plan.debit_cells {
            let mut gross: Vec<&UIntW<F>> = Vec::new();
            let mut fees: Vec<&UIntW<F>> = Vec::new();
            for (shape, wire) in plan.effects.iter().zip(&lowered.effects) {
                if shape.debit_cell() == Some(cell) {
                    let EffectW::Amount(amount) = wire else {
                        return Err(SynthFailure::Shape("Transfer/Fee effect without an amount wire".into()));
                    };
                    gross.push(amount);
                    if shape.is_fee() {
                        fees.push(amount);
                    }
                }
            }
            let g = gadgets::sum_wide(&mut cs, &format!("cell{cell}.gross"), &gross)?;
            let f = gadgets::sum_wide(&mut cs, &format!("cell{cell}.fees"), &fees)?;
            summary.push((cell, g, f));
        }
        cs.pop();
        cs.record("accounting".into(), start);
    }

    // Slot wires in layout order, then binding through the adapter.
    let duty_bool = |d: &DutyW<F>| -> BoolW<F> { d.present.clone() };
    let mut wires: Vec<SlotWire<F>> = Vec::with_capacity(layout.slots.len());
    for slot in &layout.slots {
        let wire = match slot.kind {
            SlotKind::Header(HeaderField::Cap) => {
                SlotWire::U(cap.clone().ok_or_else(|| SynthFailure::Shape("cap slot without a cap wire".into()))?)
            }
            SlotKind::Header(field) => {
                SlotWire::Const(layout.header_fields(field).ok_or_else(|| SynthFailure::Shape("header field".into()))?)
            }
            SlotKind::Input { index } => cval_wire(&inputs[index]),
            SlotKind::PreState { index } => cval_wire(&states[index]),
            SlotKind::PostState { index } => cval_wire(&lowered.states[index]),
            SlotKind::PreCell { index } => SlotWire::U(cells[index].clone()),
            SlotKind::PostCell { index } => SlotWire::U(lowered.cells[index].clone()),
            SlotKind::PreDutyPresent { index } => SlotWire::B(duty_bool(&duties[index])),
            SlotKind::PreDutyAmount { index } => SlotWire::U(duties[index].amount.clone()),
            SlotKind::PostDutyPresent { index } => SlotWire::B(duty_bool(&lowered.duties[index])),
            SlotKind::PostDutyAmount { index } => SlotWire::U(lowered.duties[index].amount.clone()),
            SlotKind::Effect { index, role } => match (&lowered.effects[index], role) {
                (EffectW::State { before, .. }, EffectRole::StateBefore) => cval_wire(before),
                (EffectW::State { after, .. }, EffectRole::StateAfter) => cval_wire(after),
                (EffectW::Amount(a), EffectRole::Amount) => SlotWire::U(a.clone()),
                (EffectW::Duty { before, .. }, EffectRole::DutyBefore) => SlotWire::U(before.clone()),
                (EffectW::Duty { after, .. }, EffectRole::DutyAfter) => SlotWire::U(after.clone()),
                (EffectW::Emit(v), EffectRole::EmitValue) => cval_wire(v),
                _ => return Err(SynthFailure::Shape(format!("effect {index} wire has no role {role:?}"))),
            },
            SlotKind::GrossDebit { cell } => SlotWire::W(
                summary.iter().find(|(c, _, _)| *c == cell).map(|(_, g, _)| g.clone()).ok_or_else(|| SynthFailure::Shape("gross row".into()))?,
            ),
            SlotKind::FeesPaid { cell } => SlotWire::W(
                summary.iter().find(|(c, _, _)| *c == cell).map(|(_, _, f)| f.clone()).ok_or_else(|| SynthFailure::Shape("fees row".into()))?,
            ),
        };
        wires.push(wire);
    }
    match relation.adapter {
        StatementAdapter::SettlementHashV2 => {
            let consts = relation.abi2.as_ref().ok_or_else(|| SynthFailure::Shape("missing ABI v2 constants".into()))?;
            let honest = match (assignment, context) {
                (None, _) => None,
                (Some(a), Some(ctx)) => {
                    let body = abi2::body_bytes(layout, plan, &a.values).map_err(|e| SynthFailure::Shape(e.to_string()))?;
                    Some(abi2::statement_bytes(consts, ctx, &body).map_err(|e| SynthFailure::Shape(e.to_string()))?)
                }
                (Some(_), None) => return Err(SynthFailure::Shape("SettlementHashV2 needs a ContextV2 to prove".into())),
            };
            abi2::bind_v2(&mut cs, consts, layout, &wires, honest.as_deref(), assignment.map(|a| a.public.as_slice()))?;
        }
        _ => relation.adapter.bind(&mut cs, layout, &wires, assignment.map(|a| a.public.as_slice()))?,
    }

    Ok(SynthesisReport { constraints: cs.num_constraints(), overrides_used: cs.overrides_used(), regions: cs.regions.clone() })
}
